  cwd: string;
  timeoutMs?: number;
  /** Optional silence budget. Cleared by the first stdout OR stderr byte. */
  startupTimeoutMs?: number;
  /** Optional caller cancellation; termination still waits for child close/reap. */
  signal?: AbortSignal;
